const today = new Date();
const month = today.getMonth() + 1;
const day = today.getDate();
const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
const dateStr = today.toLocaleDateString('en-IN', options);

const festivals = [
  { month: 1, day: 26, name: 'Republic Day' },
  { month: 2, day: 14, name: "Valentine's Day" },
  { month: 3, day: 8, name: 'Holi' },
  { month: 3, day: 25, name: 'Gudi Padwa' },
  { month: 4, day: 14, name: 'Baisakhi' },
  { month: 5, day: 12, name: "Mother's Day" },
  { month: 6, day: 16, name: "Father's Day" },
  { month: 8, day: 15, name: 'Independence Day' },
  { month: 8, day: 19, name: 'Raksha Bandhan' },
  { month: 9, day: 2, name: 'Ganesh Chaturthi' },
  { month: 10, day: 2, name: 'Gandhi Jayanti' },
  { month: 10, day: 12, name: 'Navratri' },
  { month: 10, day: 20, name: 'Dussehra' },
  { month: 11, day: 1, name: 'Diwali' },
  { month: 11, day: 5, name: 'Bhai Dooj' },
  { month: 12, day: 25, name: 'Christmas' }
];

const upcoming = festivals.filter(f => {
  const diff = (f.month - month) * 30 + (f.day - day);
  return diff >= 0 && diff <= 7;
});

const festivalHint = upcoming.length > 0
  ? '\n\n' + String.fromCodePoint(0x1F389) + ' Upcoming this week: ' + upcoming.map(f => f.name).join(', ') + ' — great time for special offers!'
  : '';

const upcomingFestivals = upcoming.map(f => f.name + ' (' + f.month + '/' + f.day + ')').join(', ');

return [{ json: {
  festivalHint,
  dateStr,
  upcomingFestivals,
  sessionId: $('Generate Session ID').first().json.sessionId
} }];

const body = $input.first().json.body;

// Handle webhook verification
if ($input.first().json.query?.['hub.mode'] === 'subscribe') {
  return [{ json: { isVerification: true, challenge: $input.first().json.query['hub.challenge'] } }];
}

const entry = body?.entry?.[0];
const change = entry?.changes?.[0]?.value;
const msg = change?.messages?.[0];
if (!msg) return [{ json: { msgType: 'status_update' } }];

// Extract the business phone number ID that RECEIVED this message
const businessPhoneId = change?.metadata?.phone_number_id || '';
const businessPhone = change?.metadata?.display_phone_number?.replace(/[^0-9]/g, '') || '';

const msgType = msg.type;
const from = msg.from;
let buttonId = null;
let text = null;
let imageId = null;
let caption = null;

if (msgType === 'interactive') {
  buttonId = msg.interactive?.button_reply?.id;
}
if (msgType === 'text') {
  text = msg.text?.body;
}
if (msgType === 'image') {
  imageId = msg.image?.id;
  caption = msg.image?.caption || '';
}

return [{ json: { msgType, from, buttonId, text, imageId, caption, businessPhoneId, businessPhone, msg } }];

const session = $('PG: Get Active Session').first().json;
const parsed = $('WA: Parse Message').first().json;

const sessionId = session?.session_id || null;
const sessionStatus = session?.status || null;
const previewImageUrl = session?.preview_image_url || null;
const from = parsed.from;
const msgType = parsed.msgType;
const buttonId = parsed.buttonId;
const text = parsed.text;
const imageId = parsed.imageId;
const caption = parsed.caption;
const businessPhoneId = parsed.businessPhoneId;
const businessPhone = parsed.businessPhone;

const createdAt = session?.created_at ? new Date(session.created_at) : null;
const isStale = createdAt ? (Date.now() - createdAt.getTime()) > 2 * 60 * 60 * 1000 : false;
const isNewSession = !sessionId || isStale;
const autoSessionId = isNewSession ? ('KS_AUTO_' + Date.now()) : sessionId;

// Client config from ks_clients JOIN
return [{ json: {
  sessionId: autoSessionId,
  sessionStatus: isNewSession ? null : sessionStatus,
  previewImageUrl: isNewSession ? null : previewImageUrl,
  from, msgType, buttonId, text, imageId, caption, businessPhoneId, businessPhone,
  hasActiveSession: !isNewSession, isNewSession,
  // Per-client config
  client_id: session?.cid || null,
  business_name: session?.business_name || 'Business',
  tagline: session?.tagline || '',
  established_year: session?.established_year || '',
  location: session?.location || '',
  brand_category: session?.brand_category || 'general',
  brand_positioning: session?.brand_positioning || '',
  phone_display: session?.phone_display || from,
  wa_phone_id: session?.wa_phone_id || '1054458951093025',
  wa_token: session?.wa_token || '',
  fb_page_id: session?.fb_page_id || '',
  fb_access_token: session?.fb_access_token || '',
  ig_node_id: session?.ig_node_id || '',
  ig_credential_id: session?.ig_credential_id || '',
  kie_api_key: session?.kie_api_key || '',
  imgbb_api_key: session?.imgbb_api_key || '',
  prompt_poster: session?.prompt_poster || '',
  prompt_enhance: session?.prompt_enhance || '',
  prompt_planner: session?.prompt_planner || '',
  prompt_morning: session?.prompt_morning || '',
  prompt_welcome: session?.prompt_welcome || ''
} }];

