const data = $input.first().json;

// Use AI-enhanced prompt if available, else fall back to base prompt
const finalPrompt = data.enhancedPrompt || data.prompt;

const validUrls = (data.imageUrls || []).filter(u => u && (u.includes('ibb.co') || u.includes('imgbb') || u.endsWith('.png') || u.endsWith('.jpg') || u.endsWith('.jpeg')));

let body;
if (validUrls.length > 0) {
  body = {
    model: 'gpt-image-2-image-to-image',
    input: {
      prompt: finalPrompt,
      input_urls: validUrls,
      aspect_ratio: '3:4',
      resolution: '1K'
    }
  };
} else {
  body = {
    model: 'gpt-image-2-text-to-image',
    input: {
      prompt: finalPrompt,
      aspect_ratio: '3:4',
      resolution: '2K'
    }
  };
}

return [{ json: {
  kieBody: JSON.stringify(body),
  from: data.from,
  sessionId: data.sessionId
} }];

